do $$
declare u uuid:=gen_random_uuid();p uuid:=gen_random_uuid();grp uuid:=gen_random_uuid();gm uuid:=gen_random_uuid();sid uuid;manual uuid;goal1 uuid:=gen_random_uuid();goal2 uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();response jsonb;first jsonb;second jsonb;
begin
 insert into auth.users(id) values(u),(outsider);
 insert into public.groups(id,name) values(grp,'VAR automatic transactional test');
 insert into public.players(id,group_id,user_id,name,nick,is_organizer) values(p,grp,u,'VAR Auto Test','Auto Test',true);
 insert into public.player_group_memberships(player_id,group_id,role) values(p,grp,'organizer') on conflict(player_id,group_id) do update set role=excluded.role;
 insert into public.games(id,group_id,scheduled_at) values(gm,grp,now());
 insert into public.attendances(game_id,player_id,status) values(gm,p,'confirmed');
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform public.pitch_var('toggle',jsonb_build_object('gameId',gm,'enabled',true));
 response:=public.pitch_var('join',jsonb_build_object('gameId',gm,'followMatchday',true,'deviceId',gen_random_uuid(),'startServerMs',extract(epoch from now()-interval '5 seconds')*1000,'uncertaintyMs',10));
 sid:=(response->>'sessionId')::uuid;
 if response->'currentMatch'<>'null'::jsonb then raise exception 'Should wait before first fixture';end if;
 if not (public.pitch_var('beat',jsonb_build_object('sessionId',sid))->>'active')::boolean then raise exception 'Waiting camera was stopped';end if;
 first:=jsonb_build_object('id','fixture-1','n',1,'events','[]'::jsonb);
 second:=jsonb_build_object('id','fixture-2','n',2,'events','[]'::jsonb);
 update public.games set live_matchday=jsonb_build_object('mode','personalizado','matches',jsonb_build_array(first,second)) where id=gm;
 response:=public.pitch_var('beat',jsonb_build_object('sessionId',sid));
 if response->'currentMatch'->>'id'<>'fixture-1' then raise exception 'Wrong first scheduled fixture';end if;
 manual:=(public.pitch_var('join',jsonb_build_object('gameId',gm,'matchId','fixture-1','deviceId',gen_random_uuid(),'startServerMs',extract(epoch from now()-interval '5 seconds')*1000,'uncertaintyMs',10))->>'sessionId')::uuid;
 first:=first||jsonb_build_object('events',jsonb_build_array(jsonb_build_object('eventId',goal1,'scorerPlayerId',p,'occurredAt',now(),'scorerId',1)));
 update public.games set live_matchday=jsonb_build_object('mode','personalizado','activeMatchId','fixture-1','matches',jsonb_build_array(first,second)) where id=gm;
 if (select count(*) from public.var_requests where goal_id=goal1)<>2 then raise exception 'Automatic and legacy camera must receive first goal';end if;
 first:=first||'{"concluded":true}'::jsonb;
 update public.games set live_matchday=jsonb_build_object('mode','personalizado','activeMatchId','fixture-2','matches',jsonb_build_array(first,second)) where id=gm;
 response:=public.pitch_var('beat',jsonb_build_object('sessionId',sid));
 if not (response->>'active')::boolean or response->'currentMatch'->>'id'<>'fixture-2' then raise exception 'Camera failed to follow next fixture';end if;
 if (public.pitch_var('beat',jsonb_build_object('sessionId',manual))->>'active')::boolean then raise exception 'Legacy fixture scope changed';end if;
 second:=second||jsonb_build_object('events',jsonb_build_array(jsonb_build_object('eventId',goal2,'scorerPlayerId',p,'occurredAt',now(),'scorerId',1)));
 update public.games set live_matchday=jsonb_build_object('mode','personalizado','activeMatchId','fixture-2','matches',jsonb_build_array(first,second)) where id=gm;
 response:=public.pitch_var('poll',jsonb_build_object('sessionId',sid));
 if jsonb_array_length(response->'requests')<>2 then raise exception 'Lost previous fixture request or next fixture goal';end if;
 if not exists(select 1 from jsonb_array_elements(response->'requests') r where r->'goal'->>'matchId'='fixture-1') or not exists(select 1 from jsonb_array_elements(response->'requests') r where r->'goal'->>'matchId'='fixture-2') then raise exception 'Original fixture identities lost';end if;
 second:=second||'{"concluded":true}'::jsonb;
 update public.games set live_matchday=jsonb_build_object('mode','personalizado','matches',jsonb_build_array(first,second)) where id=gm;
 if not (public.pitch_var('beat',jsonb_build_object('sessionId',sid))->>'active')::boolean then raise exception 'Camera stopped between fixtures';end if;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 begin perform public.pitch_var('join',jsonb_build_object('gameId',gm,'followMatchday',true));raise exception 'Outsider joined';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 update public.games set live_matchday=null where id=gm;
 if (public.pitch_var('poll',jsonb_build_object('sessionId',sid))->>'active')::boolean then raise exception 'Camera survived official end';end if;
 execute 'reset role';
end;
$$;
